const COLOR = "#00A2C2";

// brand identity: gentle glow/scale — a soft blurred halo fades in behind
// the dot alongside a light scale. Unique filter id per instance (useId)
// so this stays safe if the icon is ever rendered more than once on a
// page. No hooks/interactivity beyond useId, so this can stay a plain
// (server-renderable) component — the animation itself is pure CSS.
export default function BrandIdentityIcon() {
  const filterId = useId();
  return (
    <AnimatedIcon>
      <defs>
        <filter id={filterId} x="-100%" y="-100%" width="300%" height="300%">
          <feGaussianBlur stdDeviation="1.75" />
        </filter>
      </defs>
      <path fill="#f4f4f4" fillOpacity=".05" d={BADGE_D} />
      <circle
        cx="13.5"
        cy="10"
        r="4"
        fill={COLOR}
        filter={`url(#${filterId})`}
        className={`origin-center scale-[0.85] opacity-0 transition-[transform,opacity] ${ICON_DURATION} ${EASE_SMOOTH} ${MOTION_REDUCE} group-hover:scale-[1.5] group-hover:opacity-55 group-focus:scale-[1.5] group-focus:opacity-55`}
        style={FILL_BOX}
      />
      <g
        fill={COLOR}
        className={`origin-center transition-transform ${ICON_DURATION} ${EASE_POP} ${MOTION_REDUCE} group-hover:scale-[1.12] group-focus:scale-[1.12]`}
        style={FILL_BOX}
      >
        <path d={DOT_D} />
        <path d={TEXTURE_D} />
      </g>
    </AnimatedIcon>
  );
}
